#include <stdio.h>
int main() {
    int x = 10;
    int *ptr;
    ptr = &x;
    printf("Value of x is %d\n", x);
    printf("Address of x is %lu\n", (unsigned long) &x);
    printf("Value of pointer ptr is %lu\n", (unsigned long) ptr);
    printf("Address of pointer ptr is %lu\n", (unsigned long) &ptr);
    printf("Ptr pointing value is %d\n", *ptr);
    return 0;
}

int a[5] = {1, 2, 3, 4, 5};
int *p = a;
printf("%d ", *p++);   // 1  (in a[0] rồi p trỏ a[1])
printf("%d ", *p);     // 2
printf("%d ", (*p)++); // 2  (in rồi tăng a[1] thành 3)
printf("%d ", a[1]);   // 3
int *q = &a[4];
printf("%ld ", (long)(q - p));  // 3 phần tử
printf("%d\n", *(a + 3));       // 4

float x; int y;
void *p;          // con trỏ void
p = &x;           // p chứa địa chỉ số thực x
// *p = 2.5;      // lỗi: không truy cập trực tiếp qua void*
*((float*)p) = 2.5;   // x = 2.5
p = &y;
*((int*)p) = 2;       // y = 2

#define MAXHS 50
#define MAXLEN 30
char ds[MAXHS][MAXLEN];
char *ptr[MAXHS], *tmp;
int n = 3;
for (int i = 0; i < n; i++) ptr[i] = ds[i];   // sau khi nhập ds
for (int i = 0; i < n - 1; i++)
    for (int j = i + 1; j < n; j++)
        if (strcmp(ptr[i], ptr[j]) > 0) {
            tmp = ptr[i]; ptr[i] = ptr[j]; ptr[j] = tmp;  // đổi con trỏ, không chép xâu
        }
for (int i = 0; i < n; i++) printf("\n%d : %s", i + 1, ptr[i]);

long *arr = new long[n];
if (arr == NULL) { printf("Cap phat khong thanh cong\n"); exit(1); }
for (int i = 0; i < n; i++) scanf("%ld", &arr[i]);  // slide ghi %d
delete [] arr;

// Mảng 2 chiều R x C – con trỏ của con trỏ, một khối liền
int **mt = new int*[R];
int *temp = new int[R * C];
for (int i = 0; i < R; ++i) { mt[i] = temp; temp += C; }
delete [] mt[0];
delete [] mt;

// Hoặc cấp từng hàng
float **M = new float*[R];
for (int i = 0; i < R; i++) M[i] = new float[C];
for (int i = 0; i < R; i++) delete [] M[i];
delete [] M;

